<template><div class="page-head"><div><h2>商品分类</h2><div class="muted">维护商城左侧分类及展示图标</div></div><ElButton type="warning" @click="edit()">新增分类</ElButton></div><ElCard><ElTable :data="rows" v-loading="loading"><ElTableColumn label="图标" width="90"><template #default="s"><ElImage v-if="s.row.iconUrl" :src="s.row.iconUrl" fit="cover" style="width:46px;height:46px;border-radius:9px"/></template></ElTableColumn><ElTableColumn prop="name" label="分类名称"/><ElTableColumn prop="code" label="编码"/><ElTableColumn prop="sortNo" label="排序" width="90"/><ElTableColumn label="状态" width="100"><template #default="s"><ElTag :type="s.row.enabled?'success':'info'">{{s.row.enabled?'启用':'停用'}}</ElTag></template></ElTableColumn><ElTableColumn label="操作" width="100"><template #default="s"><ElButton link type="warning" @click="edit(s.row)">编辑</ElButton></template></ElTableColumn></ElTable></ElCard><ElDialog v-model="visible" :title="form.id?'编辑分类':'新增分类'" width="520px"><ElForm label-position="top"><ElFormItem label="分类名称"><ElInput v-model="form.name"/></ElFormItem><ElFormItem label="分类编码"><ElInput v-model="form.code" placeholder="例如 dog_snack"/></ElFormItem><ElFormItem label="分类图标"><div class="upload-row"><ElImage v-if="form.iconUrl" :src="form.iconUrl" fit="cover" class="icon"/><ElInput v-model="form.iconUrl" placeholder="上传后自动填写地址"/><ElUpload :show-file-list="false" accept="image/*" :http-request="upload"><ElButton :loading="uploading">上传</ElButton></ElUpload></div></ElFormItem><ElFormItem label="排序"><ElInputNumber v-model="form.sortNo" :min="0"/></ElFormItem><ElFormItem label="启用"><ElSwitch v-model="form.enabled"/></ElFormItem></ElForm><template #footer><ElButton @click="visible=false">取消</ElButton><ElButton type="warning" :loading="saving" @click="save">保存</ElButton></template></ElDialog></template><script setup lang="ts">import{onMounted,reactive,ref}from'vue';import{ElMessage}from'element-plus';import{api}from'../api';const rows=ref<any[]>([]),loading=ref(false),visible=ref(false),saving=ref(false),uploading=ref(false);const form=reactive<any>({id:null,name:'',code:'',iconUrl:'',sortNo:0,enabled:true});async function load(){loading.value=true;try{rows.value=await api.categories() as any[]}catch(e:any){ElMessage.error(e.message)}finally{loading.value=false}}function edit(row?:any){Object.assign(form,row?{...row}:{id:null,name:'',code:'',iconUrl:'',sortNo:0,enabled:true});visible.value=true}async function upload(o:any){uploading.value=true;try{const d:any=await api.upload(o.file);form.iconUrl=d.url;ElMessage.success('上传成功')}catch(e:any){ElMessage.error(e.message)}finally{uploading.value=false}}async function save(){if(!form.name||!form.code)return ElMessage.warning('请填写分类名称和编码');saving.value=true;try{await api.saveCategory({...form});visible.value=false;await load();ElMessage.success('保存成功')}catch(e:any){ElMessage.error(e.message)}finally{saving.value=false}}onMounted(load)</script><style scoped>.upload-row{display:flex;align-items:center;gap:10px;width:100%}.icon{width:58px;height:58px;border-radius:10px;flex:none}</style>
